(() => {
 const shell=(active,body)=>`${H.crumb(['אנשים','נועה לוי','ימים ושעות'])}${H.head('זמני הגישה של נועה לוי','ההרשאה נשמרת בפרטי האדם ונשלחת לתחנות שנבחרו.',H.btn('חזרה לעריכה','person-edit','','users'))}${H.tabs([['person-always','תמיד'],['person-timing','ימים קבועים'],['person-dates','תאריכים מסוימים']],active)}<div class="columns"><div class="card">${body}<div class="form-footer"><small>השינוי עדיין לא נשמר.</small>${H.btn('ביטול','person-edit')}${H.btn('שמירה וסנכרון','','primary','sync')}</div></div><aside class="stack">${H.card('ההרשאה הנוכחית',`<div class="person-banner">${H.person('נועה לוי','נל','קבוצת הנהלה')}</div><dl class="detail-list section-gap"><dt>דלתות מורשות</dt><dd>8</dd><dt>תוקף נוכחי</dt><dd>ב׳, ה׳ · 12:00–18:00</dd><dt>דרך האכיפה</dt><dd>Home Assistant</dd></dl>`)}${H.note('השמירה ב־WisKey והשלמת הסנכרון הן שני שלבים שונים. ניתן לעקוב אחר כל תחנה בפרטי ההרשאה.','')}</aside></div>`;
 VIEWS['person-dates']=()=>shell('person-dates',`<div class="form-section"><h3>באילו תאריכים מותר להיכנס?</h3><div class="field-grid">${H.field('הוספת תאריך','2026-09-24',{type:'date'})}${H.select('תוקף ביום הנבחר',['בשעות מסוימות','כל היום'])}</div><div class="actions section-gap"><span class="chip"><bdi>24.09.2026</bdi> ×</span><span class="chip"><bdi>25.09.2026</bdi> ×</span>${H.btn('הוספת תאריך','','small','plus')}</div></div><div class="form-section"><h3>שעות הכניסה</h3><div class="field-grid">${H.field('משעה','09:00',{type:'time',dir:'ltr'})}${H.field('עד שעה','13:00',{type:'time',dir:'ltr'})}${H.select('אזור זמן',['Asia/Jerusalem'])}${H.select('אכיפה',['Home Assistant','בתחנה — בכפוף לתאימות'])}</div></div><div class="form-section"><h3>סיכום</h3><p>ב־24 וב־25 בספטמבר, בין <bdi>09:00–13:00</bdi>, בדלתות שהוגדרו לאדם.</p><div class="section-gap">${H.note('מחוץ לתאריכים ולשעות האלה ההרשאה תוגבל. אכיפה באמצעות HA תלויה בזמינות המערכת והתחנות.','warn')}</div></div>`);
 VIEWS['person-always']=()=>shell('person-always',`<div class="form-section"><div class="choice-card selected"><i class="radio"></i><div><h3>ללא הגבלת ימים ושעות</h3><p>אפשר להיכנס בכל יום ובכל שעה, בכפוף לדלתות המורשות ולתוקף הכללי של המשתמש.</p></div></div></div><div class="form-section"><h3>מה ישתנה?</h3><div class="list-line"><span>ימים קבועים</span><span class="spacer"></span><span class="pill warn">ההגבלה תוסר</span></div><div class="list-line"><span>חלון השעות</span><span class="spacer"></span><span class="pill warn">ההגבלה תוסר</span></div><div class="list-line"><span>הדלתות המורשות</span><span class="spacer"></span><span class="pill good">ללא שינוי</span></div></div><div class="form-section"><h3>תוקף כללי</h3><p class="guide-note">למשתמש אין כרגע תאריך פקיעת תוקף. אם קיים תאריך כזה ברשומה אחרת, הוא נשאר בתוקף עד להסרה מפורשת.</p><div class="section-gap">${H.note('השינוי ייכנס לתוקף בכל תחנה לאחר סנכרון מוצלח. תחנה מנותקת תישאר ממתינה, בלי לעכב תחנות אחרות.','warn')}</div></div>`);
})();
